def calculate_user_metrics(users):
    result = []
    for i in range(len(users)):
        user = users[i]
        total = 0
        for j in range(len(user['transactions'])):
            if user['transactions'][j]['type'] == 'credit':
                total = total + user['transactions'][j]['amount']
            elif user['transactions'][j]['type'] == 'debit':
                total = total - user['transactions'][j]['amount']
        result.append({'name': user['name'], 'balance': total, 'num_transactions': len(user['transactions'])})
    return result
